const sharedCanvas = typeof document !== 'undefined' ? document.createElement('canvas') : null;
const sharedContext = sharedCanvas ? sharedCanvas.getContext('2d') : null;

export function prepareWithSegments(value, font) {
  if (font && /'Georgia',serif/.test(font)) {
    throw new Error('Use the animated monospace renderer for first-panel ASCII.');
  }

  const text = String(value || '');
  const segments = Array.from(text);
  const widths = [];

  if (sharedContext) {
    sharedContext.font = font || '16px serif';
    for (const segment of segments) {
      widths.push(sharedContext.measureText(segment).width);
    }
  } else {
    for (const segment of segments) {
      widths.push(segment === ' ' ? 4 : 8);
    }
  }

  return { segments, widths };
}
